sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // Get the current Vehicle Status value from the tracker
    var trackerStatus = current.vehicle_status + ''; // e.g. "out_on_field"

    // Safety: if no vehicle selected, there's nothing to update
    if (!current.vehicle) {
        return;
    }

    // Look up the related Loaner Vehicle record
    var vehicleGR = new GlideRecord('x_746154_loaner_0_loaner_vehicle_catalog');
    vehicleGR.addQuery('sys_id', current.vehicle); // "vehicle" is a reference field on tracker
    vehicleGR.query();

    while (vehicleGR.next()) {

        // Map tracker status -> catalog status

        // pending_release, out_on_field, returned_for_inspection, sent_for_servicing
        //  -> unavailable
        if (
            trackerStatus === 'pending_release' ||
            trackerStatus === 'out_on_field' ||
            trackerStatus === 'returned_for_inspection' ||
            trackerStatus === 'sent_for_servicing'
        ) {
            vehicleGR.status = 'unavailable';
        }

        // returned_to_warehouse -> available
        else if (trackerStatus === 'returned_to_warehouse') {
            vehicleGR.status = 'available';
        }

        // decommissioned -> decommissioned
        else if (trackerStatus === 'decommissioned') {
            vehicleGR.status = 'decommissioned';
        } else {
            // If it's some status we don't care about, don't touch the vehicle record
            return;
        }

        vehicleGR.update();
    }

})(current, previous);
